import type { LanguageCode } from '../types/index.ts';

export interface GenealogyNodeTranslation {
  name: string;
  titles: string;
  reign: string;
  spouse?: string;
  notes: string;
  sources?: string[];
}

export interface ClaimTranslation {
  topic: string;
  claim_statement: string;
  supporting_evidence: string[];
  contradictory_evidence: string[];
  source_reliability_notes: string;
  reviewer_comments: string;
}

export interface TimelineEventTranslation {
  period: string;
  year_text?: string;
  title: string;
  rulers_involved: string;
  political_development: string;
  monuments_inscriptions: string;
  primary_sources?: string;
  uncertainty_notes: string;
}

export interface LocationTranslation {
  name: string;
  ancient_name?: string;
  modern_district?: string;
  modern_state?: string;
  summary: string;
  archaeological_findings: string;
  inscriptions_found?: string[];
}

export interface DocumentTranslation {
  title: string;
  original_language?: string;
  approximate_date?: string;
  author_authority?: string;
  current_location?: string;
  source_provenance?: string;
  digitization_info?: string;
  translation_excerpt: string;
  research_notes: string;
}

export interface GalleryTranslation {
  title: string;
  period?: string;
  location?: string;
  description: string;
}

export interface GenealogyUITranslation {
  legendTitle: string;
  legendDesc: string;
  documentedBadge: string;
  traditionalBadge: string;
  corroboratedArrow: string;
  traditionalArrow: string;
  primarySourcesCount: (count: number) => string;
  consortLabel: string;
  reignEraLabel: string;
  historicalPeriodRecord: string;
  genealogicalTierLabel: string;
  suryavamshaLineage: string;
  citationsHeading: string;
  genMinus2: string;
  genMinus1: string;
  gen0: string;
  gen1: string;
  gen2: string;
  gen3: string;
  gen4: string;
  claimReviewedLabel: string;
  supportingHeading: string;
  counterHeading: string;
  viewReliabilityBtn: string;
  hideReliabilityBtn: string;
  openDossierLabel: string;
  reliabilityNotesLabel: string;
  editorialFindingLabel: string;
}

